async () => {
  const servers = ['google.com', 'cloudflare.com', 'github.com'];
  const results = {};

  for (const server of servers) {
    try {
      // Using a simple fetch request to measure response time as we can't directly use ping command
      const startTime = Date.now();
      const response = await fetch(`https://${server}`, { method: 'HEAD' });
      const endTime = Date.now();
      const responseTime = endTime - startTime;

      results[server] = {
        status: response.status,
        responseTime: responseTime
      };
    } catch (error) {
      results[server] = {
        error: error.message,
        responseTime: null
      };
    }
  }

  return results;
}

